# 세션 1 (H2 콘솔 1)
set autocommit false;
update member set money=500 where member_id='memberA';
# Update count: 1

# 락을 잡았다. 아직 커밋 안 함

# 세션 2 (H2 콘솔 2)
set autocommit false;
update member set money=1000 where member_id='memberA';

# ... 응답이 안 온다. 기다린다

# 세션 3 에서 상태 확인
select id, statement from information_schema.sessions;
# ID | STATEMENT
# 4  | null                                        <- 세션 1, 락을 쥐고 있다
# 5  | update member set money=1000 where ...       <- 세션 2, 대기 중

# 세션 1
commit;

# 세션 2 - 그제서야 응답
# Update count: 1

# 다른 행은 안 막힌다
# 세션 2
update member set money=9999 where member_id='memberB';
# Update count: 1   (즉시)

# 타임아웃을 넘기면
SET LOCK_TIMEOUT 3000;
update member set money=1000 where member_id='memberA';
# Timeout trying to lock table "MEMBER"; SQL statement: ... [50200-232]
